public class Main {
    public static void main(String[] args) {
        Cat[] 架子 = new Cat[4];
        架子[0] = new Cat("{n1}");
        架子[1] = 架子[0];
        架子[2] = 架子[0];
        架子[3] = new Cat("{n2}");
        架子[0] = null;

        int 立着的牌子 = 0;
        int 够得着的猫 = 0;
        for (int i = 0; i < 架子.length; i++) {
            if (架子[i] == null) {
                continue;
            }
            立着的牌子 = 立着的牌子 + 1;
            boolean 数过了 = false;
            for (int j = 0; j < i; j++) {
                if (架子[j] == 架子[i]) {
                    数过了 = true;
                }
            }
            if (!数过了) {
                够得着的猫 = 够得着的猫 + 1;
            }
        }
        System.out.println("还立着的牌子：" + 立着的牌子);
        System.out.println("够得着的猫：" + 够得着的猫);
    }
}

class Cat {
    String name;

    Cat(String name) {
        this.name = name;
    }
}
